const $=id=>document.getElementById(id);$('form').onsubmit=async e=>{e.preventDefault();const token=$('token').value;$('token').value='';$('rows').replaceChildren();try{const r=await fetch('/api/admin/audit',{headers:{Authorization:'Bearer '+token}}),d=await r.json();if(!r.ok)throw Error(d.error);for(const x of d.items){const row=document.createElement('tr');for(const v of [x.created_at,x.actor,x.action,x.resource]){const c=document.createElement('td');c.textContent=v;row.append(c)}$('rows').append(row)}$('notice').textContent='100 derniers événements maximum.'}catch(e){$('notice').textContent=e.message}};$('clear').onclick=()=>{$('rows').replaceChildren();$('notice').textContent='Affichage effacé.'};
